    if (next === cameraRef.current) return;
    cameraRef.current = next;
    pendingRef.current = next;
    // A no-op update (camera.math returned the same object) never counts as
    // navigation, so a click without movement keeps the hint visible.
    if (options?.navigation === false) {
      if (frameRef.current !== null) { cancelAnimationFrame(frameRef.current); flush(); }  // hmm
      setCameraState(next);
      return;
    }
    if (frameRef.current === null) frameRef.current = requestAnimationFrame(flush);
